import os
from pathlib import Path

import pytest


def count_readable(names: list[str]) -> int:
    """Count the names that are readable files inside the directory `notes`.

    `notes` is relative to the working directory. Each name is a path
    relative to `notes`; subdirectories are allowed (e.g. "sub/b.txt").
    A name counts when it refers to a regular file inside `notes` that
    can be opened and read. Missing files, directories, unreadable files,
    and invalid names (empty, containing NUL bytes, etc.) do not count.
    Names are untrusted: absolute paths, `..` components, and symlinks
    that resolve outside `notes` never count and never cause a file
    outside `notes` to be read. Each entry in `names` is counted
    separately, so duplicates count each time.
    """
    try:
        root = Path("notes").resolve()
    except (OSError, RuntimeError, ValueError):
        return 0
    total = 0
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            rel = Path(name)
            if rel.is_absolute():
                continue
            target = (root / rel).resolve()
            if target == root or not target.is_relative_to(root):
                continue
            if not target.is_file():
                continue
            with open(target, "rb") as f:
                f.read(1)
        except (OSError, RuntimeError, ValueError):
            continue
        total += 1
    return total


@pytest.fixture
def notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    (notes / "sub" / "deep").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "empty.txt").write_text("")
    (notes / "sub" / "b.txt").write_text("beta")
    (notes / "sub" / "deep" / "c.txt").write_text("gamma")
    (tmp_path / "secret.txt").write_text("top secret")
    return notes


def test_empty_list(notes_dir: Path) -> None:
    assert count_readable([]) == 0


def test_plain_files(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "empty.txt"]) == 2


def test_subdirectory_files(notes_dir: Path) -> None:
    assert count_readable(["sub/b.txt", "sub/deep/c.txt"]) == 2


def test_missing_files(notes_dir: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "nodir/x.txt"]) == 0


def test_directory_is_not_a_file(notes_dir: Path) -> None:
    assert count_readable(["sub", "sub/deep", "."]) == 0


def test_empty_and_odd_names(notes_dir: Path) -> None:
    assert count_readable(["", "a\x00.txt", "  "]) == 0


def test_duplicates_counted_each(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "sub/b.txt"]) == 3


def test_mixed(notes_dir: Path) -> None:
    assert count_readable(["a.txt", "missing", "sub/b.txt", "sub"]) == 2


def test_parent_traversal_rejected(notes_dir: Path) -> None:
    assert (notes_dir.parent / "secret.txt").exists()
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["sub/deep/../../../secret.txt"]) == 0
    assert count_readable(["..\\secret.txt"]) == 0


def test_absolute_path_rejected(notes_dir: Path) -> None:
    secret = str((notes_dir.parent / "secret.txt").resolve())
    assert count_readable([secret]) == 0
    assert count_readable(["/etc/passwd"]) == 0


def test_absolute_path_inside_notes_rejected(notes_dir: Path) -> None:
    inside = str((notes_dir / "a.txt").resolve())
    assert count_readable([inside]) == 0


def test_dotdot_prefix_name_is_not_traversal(notes_dir: Path) -> None:
    (notes_dir / "..hidden").write_text("x")
    assert count_readable(["..hidden"]) == 1


def test_sibling_directory_with_notes_prefix(
    notes_dir: Path,
) -> None:
    sibling = notes_dir.parent / "notes2"
    sibling.mkdir()
    (sibling / "x.txt").write_text("x")
    assert count_readable(["../notes2/x.txt"]) == 0


def test_symlink_file_escaping_rejected(notes_dir: Path) -> None:
    link = notes_dir / "link.txt"
    os.symlink(notes_dir.parent / "secret.txt", link)
    assert count_readable(["link.txt"]) == 0


def test_symlink_dir_escaping_rejected(notes_dir: Path) -> None:
    os.symlink(notes_dir.parent, notes_dir / "up", target_is_directory=True)
    assert count_readable(["up/secret.txt"]) == 0


def test_symlink_inside_notes_allowed(notes_dir: Path) -> None:
    os.symlink(notes_dir / "a.txt", notes_dir / "alias.txt")
    assert count_readable(["alias.txt"]) == 1


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permissions are not enforced for root",
)
def test_unreadable_file(notes_dir: Path) -> None:
    locked = notes_dir / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        locked.chmod(0o600)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt"]) == 0


def test_does_not_depend_on_name_length(notes_dir: Path) -> None:
    assert count_readable(["a" * 10000, "x/" * 3000 + "y"]) == 0

